package com.aryaa.sdm.config;
import com.aryaa.sdm.exception.ApiError; import com.fasterxml.jackson.databind.ObjectMapper; import jakarta.servlet.http.*; import org.springframework.security.core.AuthenticationException; import org.springframework.security.web.AuthenticationEntryPoint; import java.io.IOException;
public class JsonAuthenticationEntryPoint implements AuthenticationEntryPoint {private final ObjectMapper mapper=new ObjectMapper(); public void commence(HttpServletRequest req,HttpServletResponse res,AuthenticationException ex)throws IOException{res.setStatus(401);res.setContentType("application/json");res.setHeader("WWW-Authenticate","Basic realm=\"SDM Operator\"");mapper.writeValue(res.getWriter(),ApiError.of(401,"Unauthorized","Operator login required for this action."));}}
